document.addEventListener("DOMContentLoaded",function(){const t=document.getElementById("ac-power-form"),e=document.getElementById("ac-power-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const n=parseFloat(document.getElementById("ac-area").value),o=parseInt(document.getElementById("ac-people").value,10)||0,i=parseInt(document.getElementById("ac-windows").value,10)||0,a=parseFloat(document.getElementById("ac-room-type").value)||1;if(n<=0)return e.textContent="Please enter the room area.",void 0;let p=20*n;p+=600*o,p+=1e3*i,p*=a;const d=p/12e3,l=[{btu:5e3,ton:.4,type:"Small window unit"},{btu:6e3,ton:.5,type:"Medium window unit"},{btu:8e3,ton:.67,type:"Large window unit"},{btu:1e4,ton:.83,type:"Small portable/mini-split"},{btu:12e3,ton:1,type:"1-ton mini-split"},{btu:15e3,ton:1.25,type:"1.25-ton unit"},{btu:18e3,ton:1.5,type:"1.5-ton unit"},{btu:24e3,ton:2,type:"2-ton unit"},{btu:3e4,ton:2.5,type:"2.5-ton unit"}],r=l.find(t=>p<=t.btu)||l[l.length-1],s=.12*(p/1e3*1e3/10);e.innerHTML=`\n        <div class="result-section">\n          <h4>Recommended AC Capacity:</h4>\n          <p><strong>${Math.round(p).toLocaleString()} BTU/hour</strong></p>\n          <p><strong>${d.toFixed(2)} tons</strong></p>\n        </div>\n        <div class="result-recommendation">\n          <h4>Suggested Unit:</h4>\n          <p><strong>${r.btu.toLocaleString()} BTU</strong> (${r.ton} ton)</p>\n          <p>Type: ${r.type}</p>\n        </div>\n        <div class="result-breakdown">\n          <h4>Calculation Breakdown:</h4>\n          <p>Base load: ${n} sq ft × 20 BTU = ${(20*n).toLocaleString()} BTU</p>\n          ${o>0?`<p>People: ${o} × 600 BTU = ${(600*o).toLocaleString()} BTU</p>`:""}\n          ${i>0?`<p>Windows: ${i} × 1,000 BTU = ${(1e3*i).toLocaleString()} BTU</p>`:""}\n          ${1!==a?`<p>Room type adjustment: ×${a}</p>`:""}\n        </div>\n        <div class="result-tips">\n          <p><em>❄️ Consider a unit with variable speed for better efficiency</em></p>\n          <p><em>⚡ Estimated annual energy cost: ~$${s.toFixed(0)}</em></p>\n          <p><em>🏠 For whole-home cooling, consult an HVAC professional</em></p>\n        </div>\n      `})});